import{_ as s,o as t,a as p,b as e}from"./app.C41L12d5.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"矩阵计算（ISASI）","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_ISASI"},{"text":"矩阵搬入辅助配置接口","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_load_aux_config/cube_load_aux_config"},{"text":"SetLoadDataRepeatWithStride","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_load_aux_config/SetLoadDataRepeatWithStride"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/cube_compute_ISASI/cube_load_aux_config/SetLoadDataRepeatWithStride.md","filePath":"api/SIMD-API/basic_api/cube_compute_ISASI/cube_load_aux_config/SetLoadDataRepeatWithStride.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1788159000000}'),n={name:"api/SIMD-API/basic_api/cube_compute_ISASI/cube_load_aux_config/SetLoadDataRepeatWithStride.md"};function l(i,a,c,d,r,o){return t(),p("div",null,[...a[0]||(a[0]=[e(`<div><article class="markdown-body"><h1>SetLoadDataRepeatWithStride<a id="ZH-CN_TOPIC_0000002583382412"></a></h1><h2 id="产品支持情况">产品支持情况<a id="section1550532418810"></a><a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：不支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：不支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<a id="section618mcpsimp"></a><a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>&quot;basic_api/kernel_operator_mm_intf.h&quot;</code>。</p><p>用于设置<a href="../cube_compute_load/LoadDataWithStride.html">LoadDataWithStride</a>接口的repeat参数。设置repeat参数后，可以通过调用一次LoadDataWithStride接口完成多个迭代的数据搬运，还用于配置输出矩阵K轴方向偏移。</p><h2 id="函数原型">函数原型<a id="section620mcpsimp"></a><a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">SetLoadDataRepeatWithStride</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">LoadDataRepeatParamWithStride</span><span class="o">&amp;</span><span class="w"> </span><span class="n">repeatParams</span><span class="p">)</span>
</code></pre></div><h2 id="参数说明">参数说明<a id="section622mcpsimp"></a><a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 参数说明</p><table><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>repeatParams</td><td>输入</td><td>设置<a href="../cube_compute_load/LoadDataWithStride.html">LoadDataWithStride</a>接口的repeat参数，类型为SetLoadDataRepeatWithStride。<br>具体定义请参考：<code>\${INSTALL_DIR}/asc/include/basic_api/kernel_struct_mm.h</code>，<code>\${INSTALL_DIR}</code>请替换为CANN软件安装后文件存储路径。<br>参数说明请参考<a href="#table15780447181826">表2</a>。</td></tr></tbody></table><p><strong>表2</strong> LoadDataRepeatParamWithStride结构体参数说明<span id="table15780447181826"></span></p><table><thead><tr><th>参数名称</th><th>含义</th></tr></thead><tbody><tr><td>repeatStride</td><td>height/width方向上的前一个迭代与后一个迭代起始地址的距离，取值范围：repeatStride∈[0, 65535]，默认值为0。<br>    • repeatMode为0，repeatStride的单位为16个元素。<br>    • repeatMode为1，repeatStride的单位为32/sizeof(data_type)个元素，data_type指源操作数的数据类型。</td></tr><tr><td>repeatTime</td><td>height/width方向上的迭代次数，取值范围：repeatTime∈[0, 255]。默认值为1。</td></tr><tr><td>repeatMode</td><td>控制repeat迭代的方向，取值范围：repeatMode∈[0, 1]。默认值为0。<br>    • 0：迭代沿height方向；<br>    • 1：迭代沿width方向。</td></tr><tr><td>dstStride</td><td>输出矩阵K轴方向偏移，以512字节的分形为单位。</td></tr></tbody></table><h2 id="返回值说明">返回值说明<a id="section4219135304839"></a><a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="约束说明">约束说明<a id="section633mcpsimp"></a><a class="header-anchor" href="#约束说明">​</a></h2><ul><li>repeatTime=0表示不执行搬运，LoadDataWithStride接口将被视为NOP（空操作）。</li><li>调用<a href="../cube_compute_load/LoadDataWithStride.html">LoadDataWithStride</a>接口时，必须配置本接口中的dstStride参数，若不使能repeat模式，repeatTime、repeatStride、repeatMode使用默认构造值。</li></ul><h2 id="调用示例">调用示例<a id="section1761417552405"></a><a class="header-anchor" href="#调用示例">​</a></h2><p>本接口用于配合LoadDataWithStride接口使用，展示代码示例片段：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// LoadDataWithStride指令完成img2col的过程，可知 img2col后A矩阵高度为ho * wo,根据ho和wo的计算公式，代入卷积核宽度、卷积核滑动步长、卷积核膨胀系数等参数可知：A矩阵的高度为CeilAlign(k, fractalShape[0])；img2col后A矩阵宽度为ci * kh * kw，代入kh=1，kw=1，可知A矩阵的宽度为CeilAlign(m, fractalShape[1])。最后，配置loadDataParams.enTranspose = true，将整个A 矩阵转置并且将其中每一个分形转置。</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">LoadData3DParamsV2</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;</span><span class="w"> </span><span class="n">loadDataParams</span><span class="p">;</span>

<span class="c1">// 设置loadDataParams相关参数</span>
<span class="p">...</span>

<span class="c1">// 使用SetLoadDataRepeatWithStride接口，设置LoadDataWithStride接口的repeat参数</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">LoadDataRepeatParamWithStride</span><span class="w"> </span><span class="n">repeatParams</span><span class="p">;</span>
<span class="n">repeatParams</span><span class="p">.</span><span class="n">repeatTime</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">1</span><span class="p">;</span><span class="w">  </span><span class="c1">// height/width方向上的迭代次数</span>
<span class="n">repeatParams</span><span class="p">.</span><span class="n">repeatStride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">1</span><span class="p">;</span><span class="w">  </span><span class="c1">// height/width方向上前后迭代起始位置的距离</span>
<span class="n">repeatParams</span><span class="p">.</span><span class="n">repeatMode</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w">  </span><span class="c1">// 迭代方向：0：迭代沿height; 1：迭代沿width</span>
<span class="n">repeatParams</span><span class="p">.</span><span class="n">dstStride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">CeilDivision</span><span class="p">(</span><span class="n">m</span><span class="p">,</span><span class="w"> </span><span class="n">fractalShape</span><span class="p">[</span><span class="mi">0</span><span class="p">]);</span><span class="w">  </span><span class="c1">// 输出矩阵K轴方向偏移</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">SetLoadDataRepeatWithStride</span><span class="p">(</span><span class="n">repeatParams</span><span class="p">);</span>

<span class="n">AscendC</span><span class="o">::</span><span class="n">LoadDataWithStride</span><span class="p">(</span><span class="n">a2Local</span><span class="p">,</span><span class="w"> </span><span class="n">a1Local</span><span class="p">,</span><span class="w"> </span><span class="n">loadDataParams</span><span class="p">);</span>
</code></pre></div></article></div>`,1)])])}const S=s(n,[["render",l]]);export{_ as __pageData,S as default};
